import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function Dashboard() {
    const [user, setUser] = useState(null);
    const [alimentos, setAlimentos] = useState([]);
    const navigate = useNavigate();
    const [novoAlimento, setNovoAlimento] = useState({
        nome: '',
        dataValidade: '',
        quantidadeTotal: 0,
        unidadeMedida: 'KG'
    });

    useEffect(() => {
        const loggedUser = JSON.parse(localStorage.getItem('user'));
        if (!loggedUser) {
            navigate('/');
        } else {
            setUser(loggedUser);
            carregarAlimentos();
        }
    }, []);

    const carregarAlimentos = async () => {
        try {
            const response = await api.get('/alimento/disponiveis'); 
            setAlimentos(response.data);
        } catch (err) {
            console.error("Erro ao carregar alimentos", err);
        }
    };

    const handleCadastrarAlimento = async (e) => {
        e.preventDefault();
        try {
            // user.id vem do localStorage que salvamos no login
            await api.post(`/alimento/registrar/${user.id}`, novoAlimento);
            alert("Alimento cadastrado com sucesso!");
            
            // Limpa o formulário e recarrega a lista
            setNovoAlimento({ nome: '', dataValidade: '', quantidadeTotal: 0, unidadeMedida: 'KG' });
            carregarAlimentos(); 
        } catch (err) {
            alert("Erro ao cadastrar: " + (err.response?.data?.message || err.message));
        }
    };

    const handleSolicitar = async (alimentoId) => {
        const quantidadeStr = prompt("Quantos itens deseja solicitar?");
        const quantidade = parseInt(quantidadeStr);

        if (quantidade && !isNaN(quantidade)) {
            try {
                // AJUSTE DE ESTRUTURA PARA COMBINAR COM SEU DTO/SERVICE
                const payload = {
                    id: user.id, // O service usa solicitacaoDto.id() para o receptor
                    quantidade: quantidade,
                    alimento: {
                        id: alimentoId // O service usa solicitacaoDto.alimento().getId()
                    }
                };

                console.log("Enviando para o banco:", payload);

                await api.post('/solicitacao/criar', payload);
                
                alert("Solicitação enviada com sucesso!");
                carregarAlimentos(); 
            } catch (err) {
                // Exibe a mensagem de erro vinda do seu Service (ex: "Quantidade insuficiente")
                const mensagemErro = err.response?.data?.message || err.message;
                alert("Erro ao solicitar: " + mensagemErro);
                console.error(err.response?.data);
            }
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('user');
        navigate('/');
    };

    if (!user) return null;

    return (
        <div style={{ padding: '20px' }}>
            <header style={{ display: 'flex', justifyContent: 'space-between' }}>
                <h1>Food Care - Painel {user.tipoUsuario}</h1>
                <button onClick={handleLogout}>Sair</button>
            </header>

            <hr />

            {user.tipoUsuario === 'DOADOR' ? (
                <div style={{ backgroundColor: '#f9f9f9', padding: '20px', borderRadius: '8px', marginBottom: '20px' }}>
                    <h3>+ Cadastrar Novo Alimento</h3>
                    <form onSubmit={handleCadastrarAlimento} style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                        <input type="text" placeholder="Nome do Alimento" value={novoAlimento.nome}
                            onChange={(e) => setNovoAlimento({...novoAlimento, nome: e.target.value})} required />
                        
                        <input type="date" value={novoAlimento.dataValidade}
                            onChange={(e) => setNovoAlimento({...novoAlimento, dataValidade: e.target.value})} required />
                        
                        <input type="number" placeholder="Quantidade" value={novoAlimento.quantidadeTotal}
                            onChange={(e) => setNovoAlimento({...novoAlimento, quantidadeTotal: e.target.value})} required />

                        <select value={novoAlimento.unidadeMedida} 
                            onChange={(e) => setNovoAlimento({...novoAlimento, unidadeMedida: e.target.value})}>
                            <option value="KG">Quilos (KG)</option>
                            <option value="UNIDADE">Unidades</option>
                            <option value="LITRO">Litros</option>
                        </select>

                        <button type="submit" style={{ backgroundColor: 'green', color: 'white', cursor: 'pointer' }}>Salvar Doação</button>
                    </form>
                </div>
            ) : (
                <div>
                    <h3>Alimentos Disponíveis</h3>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '10px' }}>
                        {alimentos.map(alimento => (
                            <div key={alimento.id} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '8px' }}>
                                <h4>{alimento.nome}</h4>
                                <p>Validade: {alimento.dataValidade}</p>
                                <p>Qtd Disponível: {alimento.quantidadeTotal - alimento.quantidadeReservada}</p>
                                <button onClick={() => handleSolicitar(alimento.id)}>Solicitar</button>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

export default Dashboard;
